function example() {
  const Link = ({
    to,
    ...rest
  }: { to: string } & React.AnchorHTMLAttributes<HTMLAnchorElement>) => (
    <a {...rest} href={to} />
  );
  return (
    <Navbar>
      <Navbar.Menu active>
        <Navbar.Start>
          <Navbar.Item as={Link} to="#home">
            Home
          </Navbar.Item>
          <Navbar.Item as={Link} to="#pricing">
            Pricing
          </Navbar.Item>
        </Navbar.Start>
      </Navbar.Menu>
    </Navbar>
  );
}

function example() {
  const navRef = React.useRef<HTMLElement>(null);
  const [height, setHeight] = React.useState<number>();

  return (
    <>
      <Navbar ref={navRef}>
        <Navbar.Brand>
          <Navbar.Item href="#">Home</Navbar.Item>
        </Navbar.Brand>
      </Navbar>
      <Button mt="3" onClick={() => setHeight(navRef.current?.offsetHeight)}>
        Measure the navbar
      </Button>
      <p>Height: {height == null ? '—' : `${height}px`}</p>
    </>
  );
}
